function trailingZeroes(n: number): number {
  // Каждый ноль в конце — это множитель 10 = 2 * 5.
  // Двоек среди множителей n! всегда больше, чем пятёрок,
  // поэтому ответ — количество пятёрок в разложении n!
  let count = 0;

  while (n > 0) {
    // n / 5 — сколько чисел до n делятся на 5,
    // на следующем шаге — на 25, затем на 125 и т. д.
    n = Math.floor(n / 5);
    count += n;
  }

  return count;
}

// Время: O(log n) — по основанию 5
// Память: O(1)
